draw((0,0)--(6,0)--(0,4)--cycle);
label("3",(-1.5,0),N);
label("4",(0,2),E);
label("$A$",(0,4),N);
label("$B$",(-3,0),S);
label("$C$",(6,0),S);
label("$D$",(0,0),S);
